-- 39_previdenciario_base.sql — módulo Previdenciário, etapa 7: base de conhecimento e robô semanal
--
-- prev_norma        — a biblioteca: legislação, jurisprudência (temas, súmulas) e publicações
--                     oficiais, com situação (vigente, revogada, afetado, julgado) e link.
-- prev_atualizacao  — a fila do robô semanal (função robo-previdencia, segunda de manhã).
--                     O robô só SUGERE: nada entra na biblioteca nem nas tabelas de cálculo
--                     sem a aprovação do titular na tela (Previdenciário → Base).
-- prev_robo_execucao — o registro de cada rodada (o que leu, o que achou, o que falhou).
--
-- Como as tabelas oficiais (prev_parametro, prev_indice), a base é do sistema todo:
-- qualquer usuário lê; só o titular altera e decide a fila. O robô grava com a
-- chave de serviço, que passa por cima dessas regras.

create table if not exists public.prev_norma (
  id            uuid primary key default uuid_generate_v4(),
  chave         text not null unique,     -- identificador estável: 'lei-8213-1991', 'stj-rr-995'
  categoria     text not null check (categoria in ('legislacao','jurisprudencia','publicacao')),
  tipo          text not null,            -- lei, decreto, instrucao_normativa, portaria, tema_stj, sumula_tnu...
  numero        text,
  orgao         text,
  data          date,
  titulo        text not null,
  tese          text,                     -- tese fixada (jurisprudência) ou o que importa no ato
  situacao      text,
  assuntos      text[] not null default '{}',
  link          text,
  observacao    text,
  verificado    boolean not null default false,
  origem        text not null default 'manual' check (origem in ('acervo','robo','manual')),
  atualizado_fonte date,                  -- última atualização na fonte (ex.: no banco de precedentes do CNJ)
  criado_em     timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);
create index if not exists prev_norma_cat_idx on public.prev_norma(categoria, data desc);

create table if not exists public.prev_atualizacao (
  id            uuid primary key default uuid_generate_v4(),
  chave         text not null unique,     -- evita repetir o mesmo achado: 'dou-<url>', 'cnj-stj-rr-995@2026-10-01', 'inpc-2026-09'
  fonte         text not null check (fonte in ('dou','cnj','cjf','ibge','manual')),
  tipo          text not null check (tipo in ('norma','jurisprudencia','indice','noticia')),
  titulo        text not null,
  resumo        text,
  link          text,
  data          date,
  afeta_tabela  boolean not null default false,   -- pode mudar mínimo, teto, limite ou índices
  norma_chave   text,                     -- se já existe na biblioteca (atualização de tema)
  dados         jsonb not null default '{}'::jsonb,   -- o que vai para a biblioteca ou para a tabela se aprovado
  status        text not null default 'pendente' check (status in ('pendente','incorporado','descartado')),
  decidido_em   timestamptz,
  decidido_por  uuid references public.usuario(id) on delete set null,
  observacao    text,
  criado_em     timestamptz not null default now()
);
create index if not exists prev_atualizacao_status_idx on public.prev_atualizacao(status, criado_em desc);

create table if not exists public.prev_robo_execucao (
  id            uuid primary key default uuid_generate_v4(),
  iniciado_em   timestamptz not null default now(),
  terminado_em  timestamptz,
  ok            boolean,
  novos         integer not null default 0,
  resumo        jsonb not null default '{}'::jsonb   -- por fonte: lidos, novos, erro
);

-- a última "foto" de cada tema do banco de precedentes do CNJ (situação + tese), para o
-- robô avisar só do que é novo ou mudou. Só o robô (chave de serviço) lê e grava.
create table if not exists public.prev_cnj_visto (
  chave       text primary key,      -- id do CNJ: 'stj-rr-995', 'tnu-puil-25'
  assinatura  text not null,        -- resumo (hash djb2, base 36) de situação + '|' + tese
  situacao    text,
  visto_em    timestamptz not null default now()
);
alter table public.prev_cnj_visto enable row level security;

alter table public.prev_norma         enable row level security;
alter table public.prev_atualizacao   enable row level security;
alter table public.prev_robo_execucao enable row level security;

drop policy if exists prev_norma_ler on public.prev_norma;
create policy prev_norma_ler on public.prev_norma for select to authenticated using (true);
drop policy if exists prev_norma_titular on public.prev_norma;
create policy prev_norma_titular on public.prev_norma for all to authenticated
  using (meu_perfil() = 'titular') with check (meu_perfil() = 'titular');

drop policy if exists prev_atual_ler on public.prev_atualizacao;
create policy prev_atual_ler on public.prev_atualizacao for select to authenticated using (true);
drop policy if exists prev_atual_titular on public.prev_atualizacao;
create policy prev_atual_titular on public.prev_atualizacao for all to authenticated
  using (meu_perfil() = 'titular') with check (meu_perfil() = 'titular');

drop policy if exists prev_robo_ler on public.prev_robo_execucao;
create policy prev_robo_ler on public.prev_robo_execucao for select to authenticated using (true);

-- o limite do auxílio-reclusão já entrou no 38; aqui o robô só sugere e o titular lança.

-- ------------------------------------------------------------ agendamento
-- Toda segunda, 7h de Brasília (10h UTC). Mesmo molde dos outros robôs (pg_cron + pg_net).
do $$ begin
  perform cron.unschedule('robo-previdencia') where exists (select 1 from cron.job where jobname = 'robo-previdencia');
  perform cron.schedule('robo-previdencia', '0 10 * * 1', $c$
    select net.http_get(
      url := 'https://wrdfyudabvvpvfcrvvzd.supabase.co/functions/v1/robo-previdencia',
      headers := '{"apikey": "sb_publishable_EfdAshQdw1P1-lAXtlO9Hw_O8yoP3y5"}'::jsonb,
      timeout_milliseconds := 300000);
  $c$);
end $$;

-- ------------------------------------------------------------ acervo inicial
-- Conferido em 05/11/2026 nas fontes oficiais (Planalto, DOU, STF, STJ, CJF). Os marcados
-- verificado=false ficam com a ressalva na tela até você conferir.
insert into public.prev_norma (chave,categoria,tipo,numero,orgao,data,titulo,tese,situacao,assuntos,link,observacao,verificado,origem) values
('constituicao-1988-1988','legislacao','constituicao','CF/1988','Assembleia Nacional Constituinte','1988-10-05','Constituição Federal – arts. 194, 195, 201 e 203 (seguridade, custeio, RGPS e assistência/BPC)','Art. 194 define a seguridade social; art. 195 o custeio; art. 201 os princípios e riscos cobertos pelo RGPS (inclusive §1º – aposentadoria especial e PcD); art. 203, V garante o BPC de um salário mínimo à pessoa com deficiência e ao idoso sem meios de subsistência.','alterada','{aposentadoria,bpc,especial,pcd,calculo}','https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm','Texto vigente com redação da EC 103/2019. Ler sempre em conjunto com as regras de transição da EC 103/2019.',true,'acervo'),
('emenda-20-1998','legislacao','emenda','20/1998','Congresso Nacional','1998-12-16','EC 20/1998 – primeira Reforma da Previdência','Substituiu tempo de serviço por tempo de contribuição, extinguiu a aposentadoria proporcional para novos filiados e criou regras de transição (idade mínima + pedágio) para a aposentadoria proporcional; marco de 16/12/1998 para direito adquirido.','alterada','{aposentadoria,revisao,calculo}','https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc20.htm','Promulgada em 15/12/1998, publicada no DOU de 16/12/1998. Regras de transição relevantes para direito adquirido até 13/11/2019.',true,'acervo'),
('emenda-103-2019','legislacao','emenda','103/2019','Congresso Nacional','2019-11-13','EC 103/2019 – Reforma da Previdência','Instituiu idade mínima para aposentadoria programada, novo cálculo (média de 100% dos salários de contribuição desde 07/1994 e coeficiente de 60% + 2% por ano acima de 20/15 anos), regras de transição (arts. 15–21), novas regras de pensão por morte (cotas – art. 23), vedação de conversão de tempo especial após 13/11/2019 (art. 25, §2º) e regras de acumulação (art. 24).','vigente','{aposentadoria,especial,pensao,calculo,pcd,professor,incapacidade}','https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc103.htm','Promulgada em 12/11/2019 (DOU 13/11/2019). ATENÇÃO: STF, ADI 6309 (j. 03/06/2026, DJe 02/10/2026) declarou inconstitucional a idade mínima da aposentadoria especial do art. 19, §1º, I, ''a'', ''b'' e ''c'', mantendo a vedação de conversão (art. 25, §2º) e o cálculo do art. 26, §2º, IV. STF, ADI 7051: regras de pensão do art. 23 constitucionais. STF, Tema 1300: cálculo do art. 26, §2º, III (incapacidade permanente) constitucional.',true,'acervo'),
('lei_complementar-142-2013','legislacao','lei_complementar','142/2013','Congresso Nacional','2013-05-09','LC 142/2013 – aposentadoria da pessoa com deficiência no RGPS','Regulamenta o art. 201, §1º, CF: aposentadoria por tempo de contribuição da PcD com tempo reduzido conforme o grau (leve, moderada, grave) e aposentadoria por idade aos 60/55 anos com 15 anos de contribuição na condição de PcD; cálculo próprio (70%+1% por grupo de 12 contribuições na idade; 100% no tempo).','vigente','{pcd,aposentadoria,calculo}','https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp142.htm','Lei de 08/05/2013 (DOU 09/05/2013). Mantida pelo art. 22 da EC 103/2019 até lei posterior. Controvérsia sobre a média de cálculo pós-EC 103 pendente na TNU (Tema 389).',true,'acervo'),
('lei-8212-1991','legislacao','lei','8.212/1991','Congresso Nacional','1991-07-25','Lei 8.212/1991 – Lei Orgânica da Seguridade Social / Plano de Custeio','Disciplina custeio, segurados obrigatórios e contribuições (empregado, contribuinte individual, facultativo, segurado especial), salário de contribuição e obrigações das empresas; base para recolhimentos em atraso e indenização de períodos.','alterada','{carencia,qualidade-segurado,calculo,rural}','https://www.planalto.gov.br/ccivil_03/leis/l8212cons.htm','Lei de 24/07/1991 (DOU 25/07/1991), republicada em 1998. Lei 15.371/2026 alterou dispositivos (salário-paternidade), com vigência prevista para 01/01/2027.',true,'acervo'),
('lei-8213-1991','legislacao','lei','8.213/1991','Congresso Nacional','1991-07-25','Lei 8.213/1991 – Plano de Benefícios da Previdência Social','Lei central dos benefícios do RGPS: segurados e dependentes (art. 16), carência (arts. 24–27), qualidade de segurado (art. 15), cálculo (art. 29), aposentadorias, benefícios por incapacidade, auxílio-acidente, pensão, auxílio-reclusão, salário-maternidade, decadência (art. 103) e prova (art. 55, §3º).','alterada','{aposentadoria,incapacidade,acidente,pensao,reclusao,salario-maternidade,carencia,qualidade-segurado,prova,revisao,calculo,rural,especial}','https://www.planalto.gov.br/ccivil_03/leis/l8213cons.htm','Lei de 24/07/1991 (DOU 25/07/1991). Alterações recentes conferidas no texto compilado do Planalto: Lei 15.108/2025 (art. 16, §2º), Lei 15.157/2025 (arts. 43, 60 e 101), Lei 15.156/2025 (arts. 71 e 71-A – Zika), Lei 15.222/2025 (art. 71, §3º – internação), Lei 15.265/2025 (art. 60, §§ 11-A a 11-I – análise documental), Lei 15.288/2025 (art. 88, §5º), Lei 15.327/2026 (art. 115 – descontos/consignado), Lei 15.363/2026 (art. 96, §2º), Lei 15.415/2026 (art. 73-A) e Lei 15.371/2026 (salário-paternidade, vigência 2027).',true,'acervo'),
('lei-8742-1993','legislacao','lei','8.742/1993','Congresso Nacional','1993-12-08','Lei 8.742/1993 – LOAS (Benefício de Prestação Continuada)','Arts. 20 a 21-A regulam o BPC: idoso (65+) ou pessoa com deficiência, critério de renda familiar per capita (art. 20, §3º), conceito de família e de deficiência (impedimento de longo prazo), possibilidade de outros elementos probatórios da miserabilidade (§11) e revisão bienal (art. 21).','alterada','{bpc,prova}','https://www.planalto.gov.br/ccivil_03/leis/l8742.htm','Lei de 07/12/1993 (DOU 08/12/1993). STF (Temas 27 e 312) declarou inconstitucional o critério de 1/4 do SM como requisito único; STJ Tema 185 admite outros meios de prova. Lei 15.157/2025 alterou o art. 21 (dispensa de reavaliação em certas doenças).',true,'acervo'),
('lei-9876-1999','legislacao','lei','9.876/1999','Congresso Nacional','1999-11-29','Lei 9.876/1999 – fator previdenciário e período básico de cálculo','Criou o fator previdenciário e ampliou o PBC para 80% maiores salários de contribuição; art. 3º fixa a regra de transição (salários desde 07/1994) para os já filiados em 28/11/1999.','alterada','{calculo,revisao,aposentadoria}','https://www.planalto.gov.br/ccivil_03/leis/l9876.htm','Lei de 26/11/1999 (DOU 29/11/1999). Art. 3º declarado constitucional e de observância obrigatória nas ADIs 2110/2111 (2024) – fim da ''revisão da vida toda''. Após a EC 103/2019, o cálculo segue o art. 26 da EC (média de 100% desde 07/1994).',true,'acervo'),
('lei-10666-2003','legislacao','lei','10.666/2003','Congresso Nacional','2003-05-09','Lei 10.666/2003 – perda da qualidade de segurado e aposentadoria especial do cooperado','Art. 3º: a perda da qualidade de segurado não é considerada para aposentadorias por tempo de contribuição, especial e (com carência cumprida) por idade. Também trata da aposentadoria especial de cooperados.','alterada','{qualidade-segurado,aposentadoria,especial,carencia}','https://www.planalto.gov.br/ccivil_03/leis/2003/l10.666.htm','Lei de 08/05/2003 (DOU 09/05/2003).',true,'acervo'),
('lei-13135-2015','legislacao','lei','13.135/2015','Congresso Nacional','2015-06-18','Lei 13.135/2015 – pensão por morte (duração por idade do cônjuge) e auxílio-doença','Fixou duração da pensão ao cônjuge/companheiro conforme a idade do dependente e exigência de 18 contribuições e 2 anos de casamento/união estável para pensão vitalícia/tabelada (art. 77, §2º, V, Lei 8.213); demais regras de cotas posteriormente alteradas pela EC 103/2019.','vigente','{pensao,incapacidade,carencia}','https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13135.htm','Lei de 17/06/2015 (DOU 18/06/2015), conversão da MP 664/2014. Faixas etárias da pensão atualizadas por ato ministerial.',true,'acervo'),
('lei-13183-2015','legislacao','lei','13.183/2015','Congresso Nacional','2015-11-05','Lei 13.183/2015 – regra 85/95 progressiva','Incluiu o art. 29-C na Lei 8.213: afastamento do fator previdenciário quando a soma idade + tempo de contribuição atinge os pontos (85/95, progressivos). Aplicável a direitos adquiridos até 13/11/2019.','alterada','{aposentadoria,calculo}','https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13183.htm','Lei de 04/11/2015 (DOU 05/11/2015), conversão da MP 676/2015. Após a EC 103/2019 a regra de pontos passou a ser a transição do art. 15 da EC.',true,'acervo'),
('lei-13846-2019','legislacao','lei','13.846/2019','Congresso Nacional','2019-06-18','Lei 13.846/2019 – conversão da MP 871/2019 (pente-fino, prova rural, carência, reclusão, pensão)','Alterou a Lei 8.213: autodeclaração e CNIS para o segurado especial, carência na reaquisição da qualidade de segurado, auxílio-reclusão (carência de 24 meses e baixa renda pela média), exigência de início de prova material contemporânea para união estável/dependência econômica na pensão, regras de decadência e de revisão de benefícios por incapacidade.','alterada','{rural,prova,reclusao,pensao,carencia,incapacidade,revisao}','https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13846.htm','Lei de 18/06/2019. Partes do art. 103 (decadência) tiveram eficácia afastada pelo STF na ADI 6096 – conferir antes de aplicar (não verificado nesta pesquisa).',true,'acervo'),
('lei-14331-2022','legislacao','lei','14.331/2022','Congresso Nacional','2022-05-05','Lei 14.331/2022 – ações judiciais de benefícios por incapacidade e perícia','Incluiu o art. 129-A na Lei 8.213: requisitos específicos da petição inicial em ações de benefício por incapacidade (descrição da doença, documentos médicos, indeferimento etc.) e regras sobre o pagamento antecipado dos honorários periciais pelo Poder Executivo.','vigente','{incapacidade,processo,prova}','https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/lei/l14331.htm','Lei de 04/05/2022 (DOU 05/05/2022).',true,'acervo'),
('decreto-3048-1999','legislacao','decreto','3.048/1999','Presidência','1999-05-07','Decreto 3.048/1999 – Regulamento da Previdência Social (RPS)','Regulamenta custeio e benefícios do RGPS: filiação, prova de tempo, atividade especial (Anexo IV – agentes nocivos), cálculo (art. 32), atualização dos salários de contribuição (art. 33), acumulação, perícia e processo administrativo.','alterada','{aposentadoria,especial,calculo,prova,incapacidade,carencia,qualidade-segurado}','https://www.planalto.gov.br/ccivil_03/decreto/d3048.htm','Decreto de 06/05/1999 (DOU 07/05/1999, republicado em 12/05/1999). Amplamente alterado pelo Decreto 10.410/2020.',true,'acervo'),
('decreto-10410-2020','legislacao','decreto','10.410/2020','Presidência','2020-07-01','Decreto 10.410/2020 – adapta o RPS à EC 103/2019','Reescreveu o Decreto 3.048/1999 para incorporar a EC 103/2019: novas regras de aposentadoria e transição, cálculo, atividade especial (exigência de efetiva exposição e regras de EPI/PPP), pensão e acumulação.','vigente','{aposentadoria,especial,calculo,pensao}','https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/decreto/d10410.htm','Decreto de 30/06/2020 (DOU 01/07/2020). Após a ADI 6309 (2026), dispositivos do RPS que reproduzem a idade mínima da aposentadoria especial perdem fundamento – conferir regulamentação superveniente.',true,'acervo'),
('instrucao_normativa-128-2022','legislacao','instrucao_normativa','128/2022','INSS','2022-03-28','IN PRES/INSS 128/2022 – normas e procedimentos de reconhecimento de direitos no RGPS','Principal norma interna do INSS: disciplina filiação, comprovação de tempo (inclusive rural e especial – PPP), cálculo, regras de transição da EC 103, benefícios e processo administrativo. Revogou a IN 77/2015.','alterada','{aposentadoria,especial,rural,prova,calculo,processo,pcd,pensao}','https://www.in.gov.br/web/dou/-/instrucao-normativa-pres/inss-n-128-de-28-de-marco-de-2022-389275446','Assinada em 28/03/2022, DOU 29/03/2022 (Seção 1, nº 60). Alterada várias vezes (IN 133/2022 – PPP; IN 155/2023; IN 170/2024; IN 195/2025, entre outras). Link aponta para o portal do DOU (página específica não confirmada). Publicada no DOU de 29/03/2022.',true,'acervo'),
('portaria-991-2022','legislacao','portaria','991/2022','INSS','2022-03-28','Portaria DIRBEN/INSS 991/2022 – normas procedimentais em matéria de benefícios','Aprova normas procedimentais/rotinas operacionais complementares à IN 128/2022 para o reconhecimento de benefícios do RGPS (integra o conjunto de portarias DIRBEN 990 a 997 de 28/03/2022).','alterada','{processo,prova,aposentadoria,especial}','https://www.in.gov.br/web/dou/-/portaria-dirben/inss-n-991-de-28-de-marco-de-2022-389275082','Data e conteúdo confirmados apenas por fontes secundárias (COAD, okai); alterada, entre outras, pela Portaria DIRBEN/INSS 1.100/2023 (PPP físico até 31/12/2022). Conferir texto consolidado no DOU/INSS. Publicada no DOU de 29/03/2022.',true,'acervo'),
('portaria-13-2026','legislacao','portaria','13/2026','MPS/MF','2026-01-09','Portaria Interministerial MPS/MF 13/2026 – reajuste dos benefícios e valores do RGPS para 2026','Reajusta em 3,9% (INPC) os benefícios acima do mínimo a partir de 01/01/2026; piso de R$ 1.621,00 e teto de R$ 8.475,55 para salário de benefício e salário de contribuição; tabela de contribuição do empregado: 7,5% até R$ 1.621,00; 9% até R$ 2.902,84; 12% até R$ 4.354,27; 14% até R$ 8.475,55.','vigente','{tabelas,calculo}','https://www.in.gov.br/web/dou/-/portaria-interministerial-mps/mf-n-13-de-9-de-janeiro-de-2026-680382603','Assinada em 09/01/2026 (data de publicação no DOU não confirmada; fontes divergem entre 09 e 14/01/2026). Valores conferidos em fontes secundárias concordantes (Senior, RSData, Portal da Indústria); página oficial no DOU não localizada. Publicada no DOU de 12/01/2026.',true,'acervo'),
('decreto-12797-2025','legislacao','decreto','12.797/2025','Presidência','2025-12-24','Decreto 12.797/2025 – salário mínimo de 2026 (R$ 1.621,00)','Fixa o salário mínimo em R$ 1.621,00 a partir de 01/01/2026 (diário R$ 54,04; horário R$ 7,37) – piso dos benefícios previdenciários e valor do BPC.','vigente','{tabelas,bpc,calculo}','https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12797.htm','Decreto de 23/12/2025, DOU 24/12/2025.',true,'acervo'),
('portaria-79-2026','legislacao','portaria','79/2026','MPS','2026-01-13','Portaria MPS 79/2026 – fatores de atualização dos salários de contribuição (janeiro/2026)','Fixa, para janeiro de 2026, o índice de 1,002100 para atualização dos salários de contribuição no cálculo do salário de benefício (art. 33 do RPS) e das parcelas pagas em atraso (art. 175 do RPS), além de índices de pecúlios.','vigente','{tabelas,calculo}','https://www.in.gov.br/web/dou/-/portaria-mps-n-79-de-13-de-janeiro-de-2026-681153305','Os fatores saem todo mês em portaria MPS própria (ex.: nº 278 de 10/02/2026, nº 992 de 12/06/2026, nº 1.458 de 09/10/2026). Para cálculos, usar a do mês do cálculo. Publicada no DOU de 14/01/2026.',true,'acervo'),
('portaria-1458-2026','legislacao','portaria','1.458/2026','MPS','2026-10-09','Portaria MPS 1.458/2026 – fatores de atualização dos salários de contribuição (outubro/2026)','Tabela de atualização monetária dos salários de contribuição para apuração do salário de benefício (art. 33 do RPS), mês de referência outubro/2026, com fatores desde 07/1994. É a base dos índices de correção usados pela calculadora do sistema.','vigente','{tabelas,calculo}',null,'Conferida na planilha oficial do Ministério da Previdência (tabela de atualização do art. 33). Substituída a cada mês pela portaria seguinte.',true,'acervo'),
('lei-15108-2025','legislacao','lei','15.108/2025','Congresso Nacional','2025-03-14','Lei 15.108/2025 – menor sob guarda volta a ser equiparado a filho (art. 16, §2º, Lei 8.213)','Altera o art. 16, §2º, da Lei 8.213: o enteado, o menor sob tutela e o menor sob guarda judicial equiparam-se a filho, mediante declaração do segurado, desde que não possuam bens suficientes para o próprio sustento e educação.','vigente','{pensao,reclusao}','https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/L15108.htm','Lei de 13/03/2025 (data de publicação no DOU presumida 14/03/2025 – não confirmada). Tensão com o art. 23, §6º, da EC 103/2019 (STF Tema 1271 pendente, segundo fontes secundárias). Aplicação a óbitos/prisões posteriores à vigência. Link no padrão do Planalto, não acessado.',false,'acervo'),
('lei-15157-2025','legislacao','lei','15.157/2025','Congresso Nacional','2025-07-02','Lei 15.157/2025 – dispensa de reavaliação pericial (HIV/Aids, Alzheimer, Parkinson, ELA e incapacidade irreversível)','Altera arts. 43, 60 e 101 da Lei 8.213 e art. 21 da LOAS: dispensa de reavaliação para aposentados por incapacidade e beneficiários com HIV/Aids, Alzheimer, Parkinson ou ELA e quando a incapacidade for permanente/irreversível (salvo suspeita fundada de fraude ou erro); perícia de HIV/Aids com infectologista.','vigente','{incapacidade,bpc,revisao}','https://www.planalto.gov.br/ccivil_03/_Ato2023-2026/2025/Lei/L15157.htm','Lei de 01/07/2025, DOU 02/07/2025. Há ACP do MPF (2026) sobre a implementação pelo INSS.',true,'acervo'),
('lei-15265-2025','legislacao','lei','15.265/2025','Congresso Nacional','2025-11-21','Lei 15.265/2025 – benefício por incapacidade por análise documental (Atestmed) limitado a 30 dias','Incluiu os §§ 11-A e 11-F a 11-I no art. 60 da Lei 8.213: exame por telemedicina ou análise documental; duração máxima de 30 dias para o benefício concedido por análise documental, exigindo perícia presencial/telemedicina para períodos maiores; o Executivo pode excepcionar o prazo.','vigente','{incapacidade,processo,prova}','https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/L15265.htm','Publicada em DOU extra de 21/11/2025. Incorpora regras da MP 1.303/2025 (vigência encerrada). Portarias conjuntas MPS/INSS posteriores (nº 83/2025, nº 13 e 14/2026) ampliaram/disciplinaram o limite (60/90 dias somados) – conferir. Link no padrão do Planalto, não acessado.',false,'acervo'),
('lei-15415-2026','legislacao','lei','15.415/2026','Congresso Nacional','2026-05-26','Lei 15.415/2026 – prazo de 30 dias para concessão do salário-maternidade pago pelo INSS','Inclui o art. 73-A na Lei 8.213: o salário-maternidade pago diretamente pela Previdência deve ser concedido em até 30 dias do requerimento; descumprido o prazo, há concessão provisória e automática, sem repetição dos valores salvo má-fé comprovada.','vigente','{salario-maternidade,processo}','https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/L15415.htm','Lei de 25/05/2026, em vigor em 26/05/2026. Não se aplica ao salário-maternidade pago pela empresa.',true,'acervo'),
('lei-15371-2026','legislacao','lei','15.371/2026','Congresso Nacional','2026-04-01','Lei 15.371/2026 – licença-paternidade ampliada e salário-paternidade no RGPS','Amplia gradualmente a licença-paternidade e cria o salário-paternidade como benefício previdenciário, alterando CLT e Leis 8.212 e 8.213.','vigente','{salario-maternidade,calculo}','https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/L15371.htm','Lei de 31/03/2026, DOU 01/04/2026. Dispositivos das Leis 8.213/CLT com vigência prevista para 01/01/2027 (art. 14). Cronograma e regras do benefício NÃO conferidos no texto oficial. Link no padrão do Planalto, não acessado.',false,'acervo'),
('stf-rg-334','jurisprudencia','tema_stf','Tema 334','STF','2013-02-21','Direito adquirido ao melhor benefício (RE 630.501)','Para o cálculo da renda mensal inicial, cumpre observar o quadro mais favorável ao beneficiário, pouco importando o decesso remuneratório ocorrido em data posterior ao implemento das condições legais para a aposentadoria, respeitadas a decadência do direito à revisão e a prescrição quanto às prestações vencidas.','julgado','{revisao,calculo,aposentadoria}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?numero=630501&classe=RE','Rel. Min. Ellen Gracie; DJe 26/08/2013. Sujeito ao prazo decadencial do art. 103 da Lei 8.213.',true,'acervo'),
('stf-rg-350','jurisprudencia','tema_stf','Tema 350','STF','2014-09-03','Prévio requerimento administrativo como condição da ação previdenciária (RE 631.240)','I – A concessão de benefícios previdenciários depende de requerimento do interessado, não se caracterizando ameaça ou lesão a direito antes de sua apreciação e indeferimento pelo INSS, ou se excedido o prazo legal para sua análise; a exigência não se confunde com o exaurimento das vias administrativas. II – Dispensa-se o requerimento quando o entendimento da Administração for notória e reiteradamente contrário à pretensão. III – Pedidos de revisão, restabelecimento ou manutenção de benefício podem ser formulados diretamente em juízo, salvo se dependerem de matéria de fato não levada ao INSS. (+ regras de transição para ações ajuizadas até 03/09/2014.)','julgado','{processo}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=7168938','Rel. Min. Roberto Barroso; DJe 10/11/2014. ED (j. 16/12/2016) ajustaram a expressão ''data do início da ação'' nas regras de transição. Complementado pelo STJ Tema 1124 (requerimento apto / prova nova).',true,'acervo'),
('stf-rg-555','jurisprudencia','tema_stf','Tema 555','STF','2014-12-04','EPI e aposentadoria especial; ruído (ARE 664.335)','I – O direito à aposentadoria especial pressupõe a efetiva exposição do trabalhador a agente nocivo à sua saúde, de modo que, se o EPI for realmente capaz de neutralizar a nocividade, não haverá respaldo constitucional à aposentadoria especial. II – Na hipótese de exposição do trabalhador a ruído acima dos limites legais de tolerância, a declaração do empregador, no âmbito do PPP, no sentido da eficácia do EPI, não descaracteriza o tempo de serviço especial para aposentadoria.','julgado','{especial,prova}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=7734901','Rel. Min. Luiz Fux; DJe 12/02/2015. Para agentes diversos do ruído, ver STJ Tema 1090 (ônus de afastar a eficácia do EPI).',true,'acervo'),
('stf-rg-709','jurisprudencia','tema_stf','Tema 709','STF','2020-06-08','Aposentadoria especial e continuidade no trabalho nocivo (RE 791.961)','I – É constitucional a vedação de continuidade da percepção de aposentadoria especial se o beneficiário permanece laborando em atividade especial ou a ela retorna, seja essa atividade especial aquela que ensejou a aposentação precoce ou não. II – Nas hipóteses em que o segurado solicitar a aposentadoria e continuar a exercer o labor especial, a data de início do benefício será a data de entrada do requerimento, remontando a esse marco, inclusive, os efeitos financeiros; efetivada, contudo, seja na via administrativa, seja na judicial, a implantação do benefício, uma vez verificada a continuidade ou o retorno ao labor nocivo, cessará o pagamento do benefício previdenciário em questão.','julgado','{especial,aposentadoria}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=753515290','Rel. Min. Dias Toffoli; DJe 19/08/2020. ED julgados em 24/02/2021 (modulação de efeitos) e em 04/10/2021 (profissionais de saúde na pandemia) – conferir o alcance da modulação nos acórdãos dos ED.',true,'acervo'),
('stf-rg-1102','jurisprudencia','tema_stf','Tema 1102','STF','2025-11-26','Revisão da vida toda – tese cancelada e substituída após ADIs 2110/2111 (RE 1.276.977)','Nova tese (ED, 26/11/2025): ''1. A declaração de constitucionalidade do art. 3º da Lei n. 9.876/1999 impõe que o dispositivo legal seja observado de forma cogente pelos demais órgãos do Poder Judiciário e pela Administração Pública, em sua interpretação textual, que não permite exceção. O segurado do INSS que se enquadre no dispositivo não pode optar pela regra definitiva prevista no art. 29, I e II, da Lei n. 8.213/1991, independentemente de lhe ser mais favorável. 2. Ficam modulados os efeitos [...]: a) irrepetibilidade dos valores percebidos por decisões judiciais, definitivas ou provisórias, prolatadas até 5/4/24; b) impossibilidade de cobrar honorários sucumbenciais, custas e perícias contábeis dos autores de ações pendentes até essa data.''','superado','{revisao,calculo}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=795201567','A tese original (j. 01/12/2022, favorável à revisão da vida toda) foi CANCELADA nos ED (Rel. p/ acórdão Min. Alexandre de Moraes; DJe 10/03/2026), que fixaram a nova tese acima e revogaram a suspensão dos processos. Na prática: revisão da vida toda inviável.',true,'acervo'),
('stf-adi-2110-2111','jurisprudencia','outro','ADIs 2110 e 2111','STF','2024-03-21','ADIs 2110/2111 – constitucionalidade do art. 3º da Lei 9.876/1999 (fim da revisão da vida toda)','A declaração de constitucionalidade do art. 3º da Lei 9.876/1999 impõe que o dispositivo legal seja observado de forma cogente pelos demais órgãos do Poder Judiciário e pela administração pública, em sua interpretação textual, que não permite exceção. O segurado do INSS que se enquadre no dispositivo não pode optar pela regra definitiva prevista no art. 29, I e II, da Lei 8.213/1991, independentemente de lhe ser mais favorável.','julgado','{revisao,calculo}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=777166111','Rel. Min. Nunes Marques; DJe 24/05/2024; ata publicada em 05/04/2024. ED acolhidos em parte para modular (irrepetibilidade de valores recebidos por decisões até 05/04/2024; isenção de honorários/custas/perícias em ações pendentes) – DJ 10/04/2025. Novos ED na ADI 2111 rejeitados em 22/06/2026 (DJe 09/07/2026).',true,'acervo'),
('stf-rg-1209','jurisprudencia','tema_stf','Tema 1209','STF','2026-02-18','Vigilante não tem atividade especial por periculosidade (RE 1.368.225)','A atividade de vigilante, com ou sem o uso de arma de fogo, não se caracteriza como especial, para fins de concessão da aposentadoria de que trata o art. 201, § 1º, da Constituição.','julgado','{especial,aposentadoria}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=794974794','Rel. p/ acórdão Min. Alexandre de Moraes; DJe 04/03/2026. Supera, na prática, o STJ Tema 1031. O tema abrangia períodos anteriores e posteriores à EC 103/2019; verificar eventual modulação/ED antes de aplicar a períodos antigos.',true,'acervo'),
('stf-rg-1300','jurisprudencia','tema_stf','Tema 1300','STF','2025-12-18','Cálculo da aposentadoria por incapacidade permanente pós-EC 103 (RE 1.469.150)','É constitucional o pagamento do benefício de aposentadoria por incapacidade permanente nos termos fixados pelo art. 26, § 2º, III, da Emenda Constitucional nº 103/2019 para os casos em que a incapacidade para o trabalho seja constatada posteriormente à Reforma da Previdência.','julgado','{incapacidade,calculo}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=796328829','CORREÇÃO: o Tema 1300 do STF trata de incapacidade permanente (coeficiente 60% + 2%), não de pensão por morte. Rel. Min. Luís Roberto Barroso; DJe 10/04/2026. (O Tema 1300 do STJ trata de PASEP – irrelevante para o RGPS.)',true,'acervo'),
('stf-rg-27','jurisprudencia','tema_stf','Tema 27','STF','2013-04-18','BPC – critério de renda de 1/4 do salário mínimo (RE 567.985)','É inconstitucional o § 3º do artigo 20 da Lei 8.742/1993, que estabelece a renda familiar mensal per capita inferior a um quarto do salário mínimo como requisito obrigatório para concessão do benefício assistencial de prestação continuada previsto no artigo 203, V, da Constituição.','julgado','{bpc,prova}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=4614447','Rel. Min. Marco Aurélio; DJe 03/10/2013. Declaração de inconstitucionalidade sem pronúncia de nulidade; o critério legal permanece como presunção, admitindo-se outros meios de prova.',true,'acervo'),
('stf-rg-312','jurisprudencia','tema_stf','Tema 312','STF','2013-04-18','BPC – exclusão de benefícios na renda familiar (RE 580.963)','É inconstitucional, por omissão parcial, o parágrafo único do art. 34 da Lei 10.741/2003 (Estatuto do Idoso).','julgado','{bpc,calculo}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=4864062','Rel. Min. Gilmar Mendes; DJe 14/11/2013. Fundamenta a exclusão, do cálculo da renda per capita, de benefício de valor mínimo recebido por idoso ou PcD do grupo familiar (hoje também no art. 20, §14, da LOAS – não conferido nesta pesquisa).',true,'acervo'),
('stf-adi-6309','jurisprudencia','outro','ADI 6309','STF','2026-06-03','EC 103/2019 – aposentadoria especial: idade mínima inconstitucional; vedação de conversão e cálculo constitucionais','Ação julgada parcialmente procedente para reconhecer: (i) a inconstitucionalidade da imposição de idade mínima, tal como estabelecida pelo art. 19, § 1º, I, ''a'', ''b'' e ''c'', da EC nº 103/2019; e (ii) a constitucionalidade da vedação à conversão de tempo especial em tempo comum (art. 25, § 2º) e da forma de cálculo do art. 26, § 2º, IV, da EC nº 103/2019.','julgado','{especial,aposentadoria,calculo}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=801562279','Rel. Min. Luís Roberto Barroso, Rel. p/ acórdão Min. André Mendonça; DJe 02/10/2026. Decisão muito recente: verificar ED, modulação e alcance sobre a regra de transição por pontos (art. 21 da EC 103), que não foi objeto do dispositivo transcrito.',true,'acervo'),
('stf-adi-7051','jurisprudencia','outro','ADI 7051','STF',null,'EC 103/2019 – constitucionalidade das regras de cálculo da pensão por morte (cotas)','Julgado improcedente o pedido, declarando-se a constitucionalidade do art. 23 da EC 103/2019 (pensão por morte em cotas de 50% + 10% por dependente).','julgado','{pensao,calculo}','https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=771780794','Rel. Min. Luís Roberto Barroso. Confirmado o resultado (improcedência) pelo acórdão dos ED, j. 02/10/2023 (DJe 18/10/2023), e pelo ARE 1.528.624 AgR (2025). Data exata do julgamento de mérito não confirmada nesta pesquisa; tese textual não transcrita.',false,'acervo'),
('stj-rr-995','jurisprudencia','tema_stj','Tema 995','STJ','2019-10-23','Reafirmação da DER no curso do processo judicial','É possível a reafirmação da DER (Data de Entrada do Requerimento) para o momento em que implementados os requisitos para a concessão do benefício, mesmo que isso se dê no interstício entre o ajuizamento da ação e a entrega da prestação jurisdicional nas instâncias ordinárias, nos termos dos arts. 493 e 933 do CPC/2015, observada a causa de pedir.','julgado','{processo,aposentadoria,calculo}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=995&cod_tema_final=995','REsp 1.727.063, 1.727.064 e 1.727.069; Rel. Min. Mauro Campbell Marques. EDcl julgados em 19/05/2020 (DJe 21/05/2020) disciplinaram juros e honorários (sem mora do INSS se implantado em até 45 dias).',true,'acervo'),
('stj-rr-642','jurisprudencia','tema_stj','Tema 642','STJ','2015-09-09','Aposentadoria por idade rural – trabalho no campo ao completar a idade','O segurado especial tem que estar laborando no campo, quando completar a idade mínima para se aposentar por idade rural, momento em que poderá requerer seu benefício. Ressalvada a hipótese do direito adquirido, em que o segurado especial, embora não tenha requerido sua aposentadoria por idade rural, preenchera de forma concomitante, no passado, ambos os requisitos carência e idade.','julgado','{rural,aposentadoria,carencia}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=642&cod_tema_final=642','REsp 1.354.908; Rel. Min. Mauro Campbell Marques.',true,'acervo'),
('stj-rr-1007','jurisprudencia','tema_stj','Tema 1007','STJ','2019-08-14','Aposentadoria híbrida – cômputo de rural remoto e descontínuo','O tempo de serviço rural, ainda que remoto e descontínuo, anterior ao advento da Lei 8.213/1991, pode ser computado para fins da carência necessária à obtenção da aposentadoria híbrida por idade, ainda que não tenha sido efetivado o recolhimento das contribuições, nos termos do art. 48, § 3º, da Lei 8.213/1991, seja qual for a predominância do labor misto exercido no período de carência ou o tipo de trabalho exercido no momento do implemento do requisito etário ou do requerimento administrativo.','julgado','{rural,aposentadoria,carencia}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=1007&cod_tema_final=1007','REsp 1.674.221 e 1.788.404; Rel. Min. Napoleão Nunes Maia Filho. STF negou repercussão geral à matéria (Tema 1104) – não conferido nesta pesquisa.',true,'acervo'),
('stj-rr-546','jurisprudencia','tema_stj','Tema 546','STJ','2012-10-24','Lei aplicável à conversão entre tempo especial e comum','A lei vigente por ocasião da aposentadoria é a aplicável ao direito à conversão entre tempos de serviço especial e comum, independentemente do regime jurídico à época da prestação do serviço.','julgado','{especial,aposentadoria,calculo}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=546&cod_tema_final=546','REsp 1.310.034/PR; acórdão publicado em 19/12/2012. Caracterização da atividade como especial segue a lei da época da prestação (tempus regit actum). Conversão vedada para períodos após 13/11/2019 (EC 103, art. 25, §2º – ADI 6309).',true,'acervo'),
('stj-rr-422','jurisprudencia','tema_stj','Tema 422','STJ','2011-03-23','Conversão de tempo especial em comum após 28/05/1998','Permanece a possibilidade de conversão do tempo de serviço exercido em atividades especiais para comum após 1998, pois a partir da última reedição da MP n. 1.663, parcialmente convertida na Lei 9.711/1998, a norma tornou-se definitiva sem a parte do texto que revogava o referido § 5º do art. 57 da Lei n. 8.213/1991.','julgado','{especial,aposentadoria}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=422&cod_tema_final=422','REsp 1.151.363/MG; Rel. Min. Jorge Mussi; Terceira Seção; DJe 05/04/2011. Limite temporal atual: até 13/11/2019 (EC 103/2019).',true,'acervo'),
('stj-rr-534','jurisprudencia','tema_stj','Tema 534','STJ','2013-05-08','Eletricidade como agente nocivo após o Decreto 2.172/1997','As normas regulamentadoras que estabelecem os casos de agentes e atividades nocivos à saúde do trabalhador são exemplificativas, podendo ser tido como distinto o labor que a técnica médica e a legislação correlata considerarem como prejudiciais ao obreiro, desde que o trabalho seja permanente, não ocasional, nem intermitente, em condições especiais (art. 57, § 3º, da Lei 8.213/1991).','julgado','{especial,prova}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=534&cod_tema_final=534','REsp 1.306.113/SC; Rel. Min. Herman Benjamin. Data registrada = julgamento dos EDcl (08/05/2013, DJe 21/05/2013); o mérito foi julgado antes (data não confirmada aqui). Atenção: a ratio do STF no Tema 1209 (periculosidade não inerente não gera aposentadoria especial) pode ser invocada pelo INSS contra a eletricidade – acompanhar.',true,'acervo'),
('stj-rr-1031','jurisprudencia','tema_stj','Tema 1031','STJ','2020-12-09','Vigilante – especialidade com ou sem arma de fogo','É admissível o reconhecimento da especialidade da atividade de vigilante, com ou sem o uso de arma de fogo, em data posterior à Lei 9.032/1995 e ao Decreto 2.172/1997, desde que haja a comprovação da efetiva nocividade da atividade, por qualquer meio de prova até 5.3.1997, momento em que se passa a exigir apresentação de laudo técnico ou elemento material equivalente, para comprovar a permanente, não ocasional nem intermitente, exposição à atividade nociva, que coloque em risco a integridade física do segurado.','superado','{especial}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=1031&cod_tema_final=1031','REsp 1.830.508, 1.831.371 e 1.831.377; DJe 14/02/2023. SUPERADO pelo STF Tema 1209 (j. 18/02/2026): vigilância não é atividade especial. Na base do STJ o tema consta como ''Sobrestado''.',true,'acervo'),
('stj-rr-1083','jurisprudencia','tema_stj','Tema 1083','STJ','2021-11-18','Ruído variável – Nível de Exposição Normalizado (NEN)','O reconhecimento do exercício de atividade sob condições especiais pela exposição ao agente nocivo ruído, quando constatados diferentes níveis de efeitos sonoros, deve ser aferido por meio do Nível de Exposição Normalizado (NEN). Ausente essa informação, deverá ser adotado como critério o nível máximo de ruído (pico de ruído), desde que perícia técnica judicial comprove a habitualidade e a permanência da exposição ao agente nocivo na produção do bem ou na prestação do serviço.','julgado','{especial,prova}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=1083&cod_tema_final=1083','REsp 1.886.795 e 1.890.010; Rel. Min. Gurgel de Faria. Segunda parte da tese conforme texto oficial conhecido; a base consultada exibia a tese truncada após a 1ª frase.',true,'acervo'),
('stj-rr-998','jurisprudencia','tema_stj','Tema 998','STJ','2019-06-26','Auxílio-doença (acidentário ou não) computado como tempo especial','O Segurado que exerce atividades em condições especiais, quando em gozo de auxílio-doença, seja acidentário ou previdenciário, faz jus ao cômputo desse mesmo período como tempo de serviço especial.','julgado','{especial,incapacidade}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=998&cod_tema_final=998','REsp 1.759.098/RS e 1.723.181/RS; acórdão publicado em 01/08/2019. O art. 65, parágrafo único, do RPS (red. Decreto 10.410/2020) restringe ao auxílio acidentário – conflito a ser enfrentado.',true,'acervo'),
('stj-rr-416','jurisprudencia','tema_stj','Tema 416','STJ','2010-08-25','Auxílio-acidente devido ainda que mínima a lesão','Exige-se, para concessão do auxílio-acidente, a existência de lesão, decorrente de acidente do trabalho, que implique redução da capacidade para o labor habitualmente exercido. O nível do dano e, em consequência, o grau do maior esforço, não interferem na concessão do benefício, o qual será devido ainda que mínima a lesão.','julgado','{acidente,incapacidade}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=416&cod_tema_final=416','REsp 1.109.591/SC; Terceira Seção; acórdão publicado em 08/09/2010.',true,'acervo'),
('stj-rr-862','jurisprudencia','tema_stj','Tema 862','STJ','2021-06-09','Termo inicial do auxílio-acidente','O termo inicial do auxílio-acidente deve recair no dia seguinte ao da cessação do auxílio-doença que lhe deu origem, conforme determina o art. 86, § 2º, da Lei 8.213/91, observando-se a prescrição quinquenal da Súmula 85/STJ.','julgado','{acidente,incapacidade,processo}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=862&cod_tema_final=862','REsp 1.729.555 e 1.786.736; Rel. Min. Assusete Magalhães.',true,'acervo'),
('stj-rr-1124','jurisprudencia','tema_stj','Tema 1124','STJ','2025-10-08','Interesse de agir (requerimento apto) e termo inicial quando há prova não submetida ao INSS','1) Interesse de agir: o segurado deve apresentar requerimento administrativo apto; o ''indeferimento forçado'' ou a omissão na complementação após intimação afastam o interesse de agir; se o INSS não intimar para complementar prova de pedido apto, o interesse está configurado; levar a juízo fatos/provas novos exige novo requerimento (Tema 350/STF), salvo documentos meramente complementares. 2) DIB: mesmos fatos e provas → DER (ou data posterior, Tema 995); INSS que não oportunizou complementação → DER ou data posterior anterior à citação; prova surgida após o ajuizamento ou de impossível apresentação (ex.: perícia judicial de atividade especial, PPP/LTCAT novo) → citação válida ou data posterior; respeitada a prescrição quinquenal.','julgado','{processo,prova,especial,rural}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=1124&cod_tema_final=1124','REsp 1.905.830, 1.912.784 e 1.913.152; acórdão publicado em 06/11/2025 (data de julgamento conforme fontes secundárias e notícia do IEPREV). Tese oficial completa na página do STJ – aqui resumida.',true,'acervo'),
('stj-rr-185','jurisprudencia','tema_stj','Tema 185','STJ','2009-10-28','BPC – miserabilidade por outros meios de prova','A limitação do valor da renda per capita familiar não deve ser considerada a única forma de se comprovar que a pessoa não possui outros meios para prover a própria manutenção ou de tê-la provida por sua família, pois é apenas um elemento objetivo para se aferir a necessidade, ou seja, presume-se absolutamente a miserabilidade quando comprovada a renda per capita inferior a 1/4 do salário mínimo.','julgado','{bpc,prova}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=185&cod_tema_final=185','REsp 1.112.557/MG; Terceira Seção; acórdão publicado em 20/11/2009.',true,'acervo'),
('stj-rr-1090','jurisprudencia','tema_stj','Tema 1090','STJ','2025-04-09','EPI eficaz no PPP e ônus da prova (agentes diversos do ruído)','I – A informação no PPP sobre a existência de EPI descaracteriza, em princípio, o tempo especial, ressalvadas as hipóteses excepcionais nas quais, mesmo diante da comprovada proteção, o direito à contagem especial é reconhecido. II – Incumbe ao autor o ônus de comprovar: (i) a ausência de adequação ao risco da atividade; (ii) a inexistência ou irregularidade do certificado de conformidade; (iii) o descumprimento das normas de manutenção, substituição e higienização; (iv) a ausência ou insuficiência de orientação e treinamento; ou (v) qualquer outro motivo capaz de conduzir à ineficácia do EPI. III – Se a valoração da prova concluir pela presença de divergência ou de dúvida sobre a real eficácia do EPI, a conclusão deverá ser favorável ao autor.','julgado','{especial,prova}','https://processo.stj.jus.br/repetitivos/temas_repetitivos/pesquisa.jsp?novaConsulta=true&cod_tema_inicial=1090&cod_tema_final=1090','REsp 2.080.584 e 2.116.343; Rel. Min. Maria Thereza de Assis Moura. Não alcança o ruído (STF Tema 555, II).',true,'acervo'),
('stj-sum-149','jurisprudencia','sumula_stj','Súmula 149','STJ','1995-12-07','Prova exclusivamente testemunhal não basta para atividade rural','A prova exclusivamente testemunhal não basta a comprovação da atividade rurícola, para efeito da obtenção de benefício previdenciário.','julgado','{rural,prova}','https://processo.stj.jus.br/SCON/sumstj/toc.jsp?sumula=149','Terceira Seção. Aplicável também ao boia-fria (STJ Tema 554).',true,'acervo'),
('stj-sum-577','jurisprudencia','sumula_stj','Súmula 577','STJ','2016-06-22','Rural anterior ao documento mais antigo','É possível reconhecer o tempo de serviço rural anterior ao documento mais antigo apresentado, desde que amparado em convincente prova testemunhal colhida sob o contraditório.','julgado','{rural,prova}','https://processo.stj.jus.br/SCON/sumstj/toc.jsp?sumula=577','Primeira Seção. Mesma orientação do Tema 638/STJ.',true,'acervo'),
('stj-sum-576','jurisprudencia','sumula_stj','Súmula 576','STJ','2016-06-22','Termo inicial da aposentadoria por invalidez sem requerimento administrativo','Ausente requerimento administrativo no INSS, o termo inicial para a implantação da aposentadoria por invalidez concedida judicialmente será a data da citação válida.','julgado','{incapacidade,processo}','https://processo.stj.jus.br/SCON/sumstj/toc.jsp?sumula=576','Primeira Seção; DJe 27/06/2016.',true,'acervo'),
('stj-sum-416','jurisprudencia','sumula_stj','Súmula 416','STJ','2009-12-09','Pensão por morte de quem perdeu a qualidade de segurado mas tinha direito à aposentadoria','É devida a pensão por morte aos dependentes do segurado que, apesar de ter perdido essa qualidade, preencheu os requisitos legais para a obtenção de aposentadoria até a data do seu óbito.','julgado','{pensao,qualidade-segurado}','https://processo.stj.jus.br/SCON/sumstj/toc.jsp?sumula=416','Terceira Seção; DJe 16/12/2009.',true,'acervo'),
('stj-sum-340','jurisprudencia','sumula_stj','Súmula 340','STJ','2007-06-27','Lei aplicável à pensão por morte','A lei aplicável à concessão de pensão previdenciária por morte é aquela vigente na data do óbito do segurado.','julgado','{pensao}','https://processo.stj.jus.br/SCON/sumstj/toc.jsp?sumula=340','Terceira Seção. Relevante para óbitos antes/depois de 13/11/2019 (EC 103) e da Lei 15.108/2025.',true,'acervo'),
('tnu-sum-9','jurisprudencia','sumula_tnu','Súmula 9','TNU','2003-10-13','EPI não descaracteriza a especialidade do ruído','O uso de Equipamento de Proteção Individual (EPI), ainda que elimine a insalubridade, no caso de exposição a ruído, não descaracteriza o tempo de serviço especial prestado.','julgado','{especial,prova}','https://www2.cjf.jus.br/phpdoc/virtus/sumula.php?nsul=9','DJ 05/11/2003. Em harmonia com o STF Tema 555, II.',true,'acervo'),
('tnu-sum-75','jurisprudencia','sumula_tnu','Súmula 75','TNU','2013-06-12','CTPS sem defeito formal faz prova do vínculo ainda que ausente do CNIS','A Carteira de Trabalho e Previdência Social (CTPS) em relação à qual não se aponta defeito formal que lhe comprometa a fidedignidade goza de presunção relativa de veracidade, formando prova suficiente de tempo de serviço para fins previdenciários, ainda que a anotação de vínculo de emprego não conste no Cadastro Nacional de Informações Sociais (CNIS).','julgado','{prova,carencia}','https://www2.cjf.jus.br/phpdoc/virtus/sumula.php?nsul=75','DOU 13/06/2013.',true,'acervo'),
('tnu-sum-47','jurisprudencia','sumula_tnu','Súmula 47','TNU','2012-02-29','Incapacidade parcial e condições pessoais e sociais','Uma vez reconhecida a incapacidade parcial para o trabalho, o juiz deve analisar as condições pessoais e sociais do segurado para a concessão de aposentadoria por invalidez.','julgado','{incapacidade,prova}','https://www2.cjf.jus.br/phpdoc/virtus/sumula.php?nsul=47','DOU 15/03/2012.',true,'acervo'),
('tnu-puil-174','jurisprudencia','tema_tnu','Tema 174','TNU','2018-11-21','Metodologia de aferição do ruído (NHO-01/NR-15) no PPP','(a) A partir de 19 de novembro de 2003, para a aferição de ruído contínuo ou intermitente, é obrigatória a utilização das metodologias contidas na NHO-01 da FUNDACENTRO ou na NR-15, que reflitam a medição de exposição durante toda a jornada de trabalho, vedada a medição pontual, devendo constar do PPP a técnica utilizada e a respectiva norma; (b) Em caso de omissão ou dúvida quanto à indicação da metodologia empregada para aferição da exposição nociva ao agente ruído, o PPP não deve ser admitido como prova da especialidade, devendo ser apresentado o respectivo laudo técnico (LTCAT), para fins de demonstrar a técnica utilizada na medição, bem como a respectiva norma.','julgado','{especial,prova}','https://www.cjf.jus.br/publico/pdfs/05056148320174058300.pdf','PEDILEF 0505614-83.2017.4.05.8300; tese com redação dada nos embargos (DJe 21/03/2019). Complementado pelo Tema 317/TNU e, no STJ, pelo Tema 1083 (NEN).',true,'acervo'),
('tnu-puil-317','jurisprudencia','tema_tnu','Tema 317','TNU','2024-06-26','Menção a ''dosimetria'' no PPP não basta para provar NHO-01/NR-15','A menção à dose, dosímetro ou dosimetria no PPP não é suficiente para se concluir pela observância das determinações da Norma de Higiene Ocupacional (NHO-01) da FUNDACENTRO e/ou da NR-15, nos termos do Tema 174 da TNU. É necessário menção expressa às referidas normas para indicar que as técnicas e metodologias utilizadas na aferição do ruído seguiram todos os seus preceitos.','julgado','{especial,prova}','https://www.cjf.jus.br/publico/pdfs/50006482820204025002-TEMA317.pdf','DJe 02/07/2024.',true,'acervo'),
('tnu-puil-389','jurisprudencia','tema_tnu','Tema 389','TNU',null,'Aposentadoria da PcD – cálculo após a EC 103/2019 (art. 26 da EC x art. 29 da Lei 8.213)','Questão submetida: saber se a regra geral de cálculo do salário-de-benefício da aposentadoria voluntária trazida no artigo 26 da EC nº 103/2019 revogou o critério previsto no artigo 29 da Lei nº 8.213/91 para a aposentadoria da pessoa com deficiência prevista na LC 142/2013. Sem tese fixada.','afetado (pendente)','{pcd,calculo,aposentadoria}','https://www.cjf.jus.br/cjf/corregedoria-da-justica-federal/turma-nacional-de-uniformizacao/temas-representativos?tema=389&submitted=Buscar','Situação ''Em julgamento'' na base consultada (nov/2026). Data de afetação não confirmada.',false,'acervo')
on conflict (chave) do nothing;

